var FETCH_DIRECTIVES = ['default-src','script-src','style-src','img-src','font-src','connect-src','media-src','object-src','frame-src','worker-src','manifest-src','child-src'];
var OTHER_DIRECTIVES = ['base-uri','form-action','frame-ancestors','report-uri','report-to','upgrade-insecure-requests','block-all-mixed-content','require-trusted-types-for','sandbox'];
var KEYWORDS = ["'self'","'none'","'unsafe-inline'","'unsafe-eval'","'strict-dynamic'","'unsafe-hashes'","'wasm-unsafe-eval'"];
function parsePolicy(str){
  var out={directives:{}, order:[], errors:[]};
  var s=String(str||'').replace(/^\s*content-security-policy(-report-only)?\s*:\s*/i,'');
  var segs=s.split(';');
  for(var i=0;i<segs.length;i++){
    var seg=segs[i].trim();
    if(!seg) continue;
    var toks=seg.split(/\s+/);
    var name=toks.shift().toLowerCase();
    if(out.directives.hasOwnProperty(name)){ out.errors.push('重复指令: '+name+'（浏览器只取第一个）'); continue; }
    out.directives[name]=toks;
    out.order.push(name);
  }
  return out;
}
function serialize(dirs, order){
  var keys = order && order.length ? order : Object.keys(dirs);
  var parts=[];
  for(var i=0;i<keys.length;i++){
    var k=keys[i];
    if(!dirs.hasOwnProperty(k)) continue;
    var v=dirs[k];
    parts.push(v && v.length ? (k+' '+v.join(' ')) : k);
  }
  return parts.join('; ');
}
function isSourceValid(src){
  var s=String(src||'').trim();
  if(!s) return false;
  if(KEYWORDS.indexOf(s)>-1) return true;
  if(/^'nonce-[A-Za-z0-9+/=_-]{8,}'$/.test(s)) return true;
  if(/^'sha(256|384|512)-[A-Za-z0-9+/=]+'$/.test(s)) return true;
  if(s==='*' ) return true;
  if(/^[a-z][a-z0-9+.-]*:$/i.test(s)) return true;
  if(/^\*\.[^\s*]+$/.test(s)) return true;
  if(/^(https?:\/\/)?[^\s'";]+$/.test(s)) return true;
  return false;
}
function auditPolicy(str){
  var p=parsePolicy(str), issues=[], d=p.directives;
  function add(level,msg){ issues.push({level:level, msg:msg}); }
  for(var i=0;i<p.errors.length;i++) add('error', p.errors[i]);
  var known = FETCH_DIRECTIVES.concat(OTHER_DIRECTIVES);
  for(var k in d){
    if(!d.hasOwnProperty(k)) continue;
    if(known.indexOf(k)===-1) add('info','未识别指令: '+k);
    var vals=d[k];
    for(var j=0;j<vals.length;j++){
      if(!isSourceValid(vals[j])) add('error','非法源表达式: '+k+' '+vals[j]);
    }
  }
  if(!d['default-src'] && !d['script-src']) add('error','缺少 default-src 与 script-src，脚本无任何限制');
  var script = d['script-src'] || d['default-src'] || [];
  if(script.indexOf("'unsafe-inline'")>-1){
    var hasNonce = script.some(function(v){ return /^'nonce-/.test(v) || /^'sha\d/.test(v); });
    if(hasNonce) add('info',"script-src 同时含 nonce/hash 与 'unsafe-inline'：CSP3 浏览器会忽略 unsafe-inline，仅作旧浏览器降级");
    else add('error',"script-src 允许 'unsafe-inline'，XSS 防护基本失效");
  }
  if(script.indexOf("'unsafe-eval'")>-1) add('warn',"script-src 允许 'unsafe-eval'，eval/new Function 可被利用");
  if(script.indexOf('*')>-1) add('error','script-src 使用通配符 *，等同不设防');
  if(script.indexOf('data:')>-1) add('error','script-src 允许 data:，可被注入任意脚本');
  if(script.indexOf('http:')>-1) add('warn','script-src 允许明文 http:，存在中间人注入风险');
  var style = d['style-src'] || d['default-src'] || [];
  if(style.indexOf("'unsafe-inline'")>-1) add('warn',"style-src 允许 'unsafe-inline'，存在样式注入与数据泄露风险");
  if(!d['object-src'] && !(d['default-src']||[]).length) add('warn',"建议显式设置 object-src 'none' 以封堵 Flash/插件向量");
  else {
    var obj = d['object-src'] || d['default-src'];
    if(obj.indexOf("'none'")===-1) add('warn',"object-src 建议设为 'none'");
  }
  if(!d['base-uri']) add('warn',"缺少 base-uri，攻击者可注入 <base> 劫持相对路径");
  if(!d['frame-ancestors']) add('warn',"缺少 frame-ancestors，无法防御点击劫持");
  if(!d['form-action']) add('info','建议设置 form-action 限制表单提交目标');
  if(script.indexOf("'strict-dynamic'")>-1 && !script.some(function(v){return /^'nonce-|^'sha\d/.test(v);}))
    add('error',"'strict-dynamic' 必须配合 nonce 或 hash 使用");
  var errors=0, warnings=0, infos=0;
  for(var q=0;q<issues.length;q++){
    if(issues[q].level==='error') errors++;
    else if(issues[q].level==='warn') warnings++;
    else infos++;
  }
  var score = 100 - errors*25 - warnings*8;
  if(score<0) score=0;
  var grade = errors>0 ? (score>=50?'C':score>0?'D':'F') : (warnings===0?'A': warnings<=2?'B':'C');
  return {parsed:p, issues:issues, errors:errors, warnings:warnings, infos:infos, score:score, grade:grade};
}
function buildPolicy(opt){
  opt=opt||{};
  var d={}, order=[];
  function set(k,v){ d[k]=v; order.push(k); }
  var mode = opt.mode || 'strict';
  if(mode==='strict'){
    var script=["'strict-dynamic'"];
    if(opt.nonce) script.unshift("'nonce-"+opt.nonce+"'");
    script.push('https:',"'unsafe-inline'");
    set('default-src',["'self'"]);
    set('script-src', script);
    set('object-src',["'none'"]);
    set('base-uri',["'self'"]);
    set('frame-ancestors',["'none'"]);
    set('form-action',["'self'"]);
  } else if(mode==='basic'){
    set('default-src',["'self'"]);
    set('script-src',["'self'"]);
    set('style-src',["'self'","'unsafe-inline'"]);
    set('img-src',["'self'",'data:','https:']);
    set('object-src',["'none'"]);
    set('base-uri',["'self'"]);
    set('frame-ancestors',["'self'"]);
    set('form-action',["'self'"]);
  } else if(mode==='lockdown'){
    set('default-src',["'none'"]);
    set('script-src',["'self'"]);
    set('style-src',["'self'"]);
    set('img-src',["'self'"]);
    set('connect-src',["'self'"]);
    set('font-src',["'self'"]);
    set('base-uri',["'none'"]);
    set('frame-ancestors',["'none'"]);
    set('form-action',["'self'"]);
  } else {
    set('default-src',["'self'"]);
  }
  if(opt.extra){
    for(var k in opt.extra){
      if(!opt.extra.hasOwnProperty(k)) continue;
      if(d.hasOwnProperty(k)){
        var cur=d[k].slice();
        var add=opt.extra[k];
        for(var i=0;i<add.length;i++) if(cur.indexOf(add[i])===-1) cur.push(add[i]);
        d[k]=cur;
      } else set(k, opt.extra[k]);
    }
  }
  if(opt.upgradeInsecure){ d['upgrade-insecure-requests']=[]; order.push('upgrade-insecure-requests'); }
  if(opt.reportUri){ d['report-uri']=[opt.reportUri]; order.push('report-uri'); }
  var value=serialize(d, order);
  var name = opt.reportOnly ? 'Content-Security-Policy-Report-Only' : 'Content-Security-Policy';
  return {directives:d, order:order, value:value, header:name+': '+value, reportOnly: !!opt.reportOnly};
}
function makeNonce(seed){
  var s=String(seed===undefined? 'nano':seed), h=2166136261;
  var A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789', out='';
  for(var i=0;i<s.length;i++){ h ^= s.charCodeAt(i); h = (h*16777619)>>>0; }
  for(var j=0;j<22;j++){ h = (h*1103515245 + 12345)>>>0; out += A.charAt(h % A.length); }
  return out;
}
function diffPolicy(a,b){
  var pa=parsePolicy(a).directives, pb=parsePolicy(b).directives;
  var added=[], removed=[], changed=[];
  for(var k in pb){ if(pb.hasOwnProperty(k) && !pa.hasOwnProperty(k)) added.push(k); }
  for(var j in pa){ if(pa.hasOwnProperty(j) && !pb.hasOwnProperty(j)) removed.push(j); }
  for(var m in pa){
    if(!pa.hasOwnProperty(m) || !pb.hasOwnProperty(m)) continue;
    if(pa[m].join(' ')!==pb[m].join(' ')) changed.push({name:m, from:pa[m], to:pb[m]});
  }
  return {added:added, removed:removed, changed:changed, same: !added.length && !removed.length && !changed.length};
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { FETCH_DIRECTIVES:FETCH_DIRECTIVES, OTHER_DIRECTIVES:OTHER_DIRECTIVES, KEYWORDS:KEYWORDS, parsePolicy:parsePolicy, serialize:serialize, isSourceValid:isSourceValid, auditPolicy:auditPolicy, buildPolicy:buildPolicy, makeNonce:makeNonce, diffPolicy:diffPolicy }; }
if (typeof window !== 'undefined') { window.CspForgePure = { FETCH_DIRECTIVES:FETCH_DIRECTIVES, OTHER_DIRECTIVES:OTHER_DIRECTIVES, KEYWORDS:KEYWORDS, parsePolicy:parsePolicy, serialize:serialize, isSourceValid:isSourceValid, auditPolicy:auditPolicy, buildPolicy:buildPolicy, makeNonce:makeNonce, diffPolicy:diffPolicy }; }
